    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    total = sum(a)

    # If total chocolates is 0 or 1, impossible to divide by k > 1
    if total <= 1:
        return '-1'

    min_cost = float('inf')

    # Check k up to 10^6 (max constraint on a_i) or total
    # Since we need k to divide total, we can early skip
    limit = min(total, 10**6)

    for k in range(2, limit + 1):
        if total % k != 0:
            continue

        # Calculate cost for this k
        # At each position, accumulate chocolates and track remainder
        cost = 0
        acc = 0
        for x in a:
            acc = (acc + x) % k
            cost += acc

        if cost < min_cost:
            min_cost = cost

        # Early exit if we can't do better
        if min_cost == 0:
            return '0'

    if min_cost == float('inf'):
        return '-1'
    return str(min_cost)

