    if not lines:
        return "0"

    n = int(lines[0])
    strings = lines[1:n + 1]

    total = 0

    for i in range(n):
        for j in range(i + 1, n):
            s1 = strings[i]
            s2 = strings[j]

            # If lengths differ, they can never be equal
            if len(s1) != len(s2):
                total += 1337
            # If strings are identical, f(s_i, s_j) = 0
            elif s1 == s2:
                total += 0
            # If they are anagrams (same characters), f(s_i, s_j) = 1
            # We can sort one of them to match the other
            elif sorted(s1) == sorted(s2):
                total += 1
            # If they have different character counts, impossible to make equal
            else:
                total += 1337

    return str(total)

