def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, prev_count, prev_removed):
        if i == n:
            return 0

        if a[i] == 0:
            return dp(i + 1, 0, 0)

        # Option 1: Use a type 1 operation that extends the previous range
        # This removes 1 element from position i if we're continuing a range
        cost1 = float('inf')
        if prev_removed > 0:
            cost1 = dp(i + 1, 0, 0) + 1

        # Option 2: Divide current position into type 1 and type 2 operations
        # We can use some number of type 1 operations and the rest with type 2
        cost2 = float('inf')
        for k in range(1, min(a[i], prev_removed + 1) + 1):
            cost2 = min(cost2, k + dp(i + 1, 0, 0) - prev_removed if prev_removed else k + dp(i + 1, 0, 0))

        # Option 3: Just use type 2 operations for this position
        cost3 = float('inf')
        cost3 = dp(i + 1, 0, 0) + a[i]

        # Option 4: Combine - calculate by considering range operations
        # For element i, we can remove some using range ops from prev_removed
        # and the rest with individual ops
        cost4 = 0
        if prev_removed > 0:
            cost4 = dp(i + 1, 0, 0) + (a[i] // prev_removed + (1 if a[i] % prev_removed else 0))
            if prev_removed > a[i]:
                cost4 = dp(i + 1, 0, 0) + 1

        return min(cost1, cost2, cost3, cost4)

    return str(dp(0, a[0] if n > 0 else 0, 1))

