class Solution:
    def solve(self):
        data = input_data.split('\n')
        n, q = map(int, data[0].split())

        # Read the probabilities
        p = []
        p_zero = []
        for i in range(n):
            a, b = map(int, data[1 + i].split())
            # p = a/(a+b), q = b/(a+b)
            if b == 0:
                prob = 1.0
            else:
                prob = a / (a + b)
            p.append(prob)

        output = []

        # Build prefix products for efficiency
        # prefix[p] = product of p[i]/(1-p[i]) for i in range
        prefix = [1.0] * (n + 1)
        for i in range(n):
            if p[i] == 1.0:
                ratio = float('inf')
            else:
                ratio = p[i] / (1 - p[i])
            prefix[i + 1] = prefix[i] * (float('inf') if ratio == float('inf') else ratio)

        def get_prob(i):
            # Get product p[0..i-1]/(1-p[0..i-1])
            if i == 0:
                return 1.0
            if prefix[i - 1] == float('inf') or float('inf') in [prefix[i-1], prefix[i-1]/ratio]:
                return float('inf')
            ratio = p[i - 1] / (1 - p[i - 1]) if p[i - 1] < 1 else float('inf')
            return prefix[i - 1] * ratio if ratio != float('inf') else float('inf')

        # Process queries
        idx = 1 + n
        for _ in range(q):
            q_parts = data[idx].split()
            idx += 1

            if q_parts[0] == '1':
                # Update type 1
                i, a, b = int(q_parts[1]), int(q_parts[2]), int(q_parts[3])
            else:
                # Query type 2
                l, r = int(q_parts[1]), int(q_parts[2])
                # Compute probability
                result = self.query_probability(p, l, r)
                output.append(f"{result:.10f}")

        return '\n'.join(output)

    def query_probability(self, p, l, r):
        # Compute probability to dominate on [l, r]
        # This involves a series formula

        eps = 1e-14

        # Build the geometric series sum
        # The probability is related to sum of products of ratios

        # For each step, ratio = p/(1-p)
        # We need sum_{k=0}^{r-l} product of ratios from l to l+k

        result = 0.0
        current = 1.0

        for k in range(r - l + 1):
            val = current
            result += val
            current *= p[l + k - 1] / (1 - p[l + k - 1]) + eps

        # The final answer is 1 / (1 + sum)
        if result == 0:
            return 1.0
        return 1.0 / (1.0 + result)

