    m = int(lines[2])

    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes by descending strength
    sorted_heroes = sorted(range(n), key=lambda i: strengths[i], reverse=True)
    sorted_vals = [strengths[i] for i in sorted_heroes]

    @lru_cache(maxsize=None)
    def dp(move, count_used):
        """
        move: current action index (0 to m-1)
        count_used: number of heroes processed so far (picked or banned)
        Returns (team1_strength - team2_strength) from remaining moves
        """
        if move == m:
            return 0

        action, team = actions[move]

        # We greedily use heroes in sorted order
        next_hero_idx = count_used
        if next_hero_idx >= len(sorted_vals):
            return 0

        val = sorted_vals[next_hero_idx]
        new_count = next_hero_idx + 1

        if action == 'p':
            if team == 1:
                return val + dp(move + 1, new_count)
            else:
                return -val + dp(move + 1, new_count)
        else:  # 'b' - ban, hero removed but doesn't help anyone
            return dp(move + 1, new_count)

    return str(dp(0, 0)) + '\n'

