def find_mst_weight(edges, n):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    # Sort edges by weight
    edges_sorted = sorted(edges, key=lambda x: x[2])

    mst_weight = 0
    edges_count = 0

    for u, v, w in edges_sorted:
        if union(u, v):
            mst_weight += w
            edges_count += 1
            if edges_count == n - 1:
                break

    if edges_count < n - 1:
        return float('inf')

    return mst_weight

