        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1
            return True

        mst_weight = 0
        edges_count = 0

        for u, v, w in s_edges_sorted:
            if union(u, v):
                mst_weight += w
                edges_count += 1
                if edges_count == n - 1:
                    break

        if edges_count < n - 1:
            # Need to connect remaining components
            # Minimum weight would be 1 or small
            mst_weight += (n - 1 - edges_count)

        return mst_weight

def compute_prefix_function(pattern):
    m = len(pattern)
    pi = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and pattern[k] != pattern[q]:
            k = pi[k - 1]
        if pattern[k] == pattern[q]:
            k += 1
        pi[q] = k
    return pi

