    lines = grid_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:n+1]]

    # Get all neighbors (including diagonals for king's graph)
    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbors.append((nr, nc))
        return neighbors

    # Parse grid to integers - '0' stays empty
    grid_int = [['' for _ in range(m)] for _ in range(n)]
    for r in range(n):
        for c in range(m):
            char = grid[r][c]
            if char != '0':
                grid_int[r][c] = int(char)

    # Check if any pre-colored cells already violate constraints among themselves
    for r1 in range(n):
        for c1 in range(m):
            color1 = grid_int[r1][c1]
            if color1 == '':
                continue
            for nr, nc in get_neighbors(r1, c1):
                color2 = grid_int[nr][nc]
                if color2 != '' and color1 == color2:
                    return '0\n'

    # Result grid to fill
    result = [['' for _ in range(m)] for _ in range(n)]

    # Precompute adjacency for efficiency
    adjacency = {}
    for r in range(n):
        for c in range(m):
            adjacency[(r, c)] = get_neighbors(r, c)

    def is_valid(r, c, color):
        for nr, nc in adjacency[(r, c)]:
            if result[nr][nc] == color:
                return False
        return True

    def solve(cell):
        if cell == n * m:
            return True

        r, c = cell // m, cell % m

        # If already pre-colored, skip validation (already checked)
        if grid_int[r][c] != '':
            result[r][c] = grid_int[r][c]
            return solve(cell + 1)

        # Try colors 1-4
        for color in [1, 2, 3, 4]:
            if is_valid(r, c, color):
                result[r][c] = color
                if solve(cell + 1):
                    return True
                result[r][c] = ''

        return False

    if solve(0):
        output_lines = []
        for row in result:
            output_lines.append(''.join(str(c) for c in row))
        return '\n'.join(output_lines) + '\n'
    else:
        return '0\n'


