    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    d = list(map(int, lines[1].split()))
    h = list(map(int, lines[2].split()))

    qs = [tuple(map(int, line.split())) for line in lines[3:]]

    # Prefix sums for distance calculations
    # d[i-1] is the distance from tree i to i+1 (1-indexed)
    # pref[i] = sum of d[0] to d[i-1]
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + d[i]

    total_dist = pref[n]

    # Build sparse table for RMQ on heights
    K = (n).bit_length() if n > 0 else 1
    st = [[h[i]] for i in range(n)]

    for j in range(1, K):
        for i in range(n - (1 << j) + 1):
            st[j][i] = max(st[j-1][i], st[j-1][i + (1 << (j-1))])

    def get_max_height(l, r):
        if l > r:
            return -float('inf')
        length = r - l + 1
        j = (length).bit_length() - 1
        return max(st[j][l], st[j][r - (1 << j) + 1])

    def get_height(l, r):
        if l > r:
            return -float('inf')
        return h[r] if l <= r else -float('inf')

    def calc_dist(x, y, a, b):
        dist1 = abs(pref[x + 1] - pref[y + 1])
        if a <= b:
            # Blocked range is [a, b] (1-indexed)
            # Safe segments are [0, a-2] and [b, n-1] in 0-based
            path_blocked = (x < a - 1 and y >= a - 1) or (x >= a - 1 and y >= a - 1) or \
                           (x < b and y >= b) or (x >= b and y < b)
            return dist1 if not path_blocked else total_dist - dist1
        else:
            # Blocked range is [n, 1], [n-1, b], [a, n]
            # Handle more complex blocked ranges
            pass

    results = []

    for a, b in qs:
        if a > b:
            a, b = b, a

        # Now a <= b
        # Blocked range [a, b] (1-indexed) -> [a-1, b-1] (0-indexed)
        L, R = a - 1, b - 1

        # Safe segments (in 0-indexed):
        seg1 = [i for i in range(L)]  # [0, L-1]
        seg2 = [i for i in range(R + 1, n)]  # [R+1, n-1]

        # Convert seg1 and seg2 to circular indices
        safe_trees = seg1 + seg2

        max_energy = 0

        if len(safe_trees) >= 2:
            # Try all pairs from the safe trees
            for i in range(len(safe_trees)):
                for j in range(i + 1, len(safe_trees)):
                    x = safe_trees[i]
                    y = safe_trees[j]

                    # Calculate distance - must not go through blocked range
                    # There are two paths between x and y: one goes through the blocked range
                    # We take the one that doesn't go through the blocked range

                    # Path going forward from x to y:
                    # If x < y: path length is pref[y+1] - pref[x+1]
                    # If x > y: path length is total_dist - (pref[x+1] - pref[y+1])

                    if x < y:
                        path_len = pref[y + 1] - pref[x + 1]
                    else:
                        path_len = total_dist - (pref[x + 1] - pref[y + 1])

                    # Check if this path goes through the blocked range [L, R]
                    # Path from x to y going forward
                    if x < y:
                        if x <= L and y <= R:
                            # Path goes through blocked range
                            abs_dist = total_dist - path_len
                        else:
                            abs_dist = path_len
                    else:
                        # Path wraps around
                        if x <= L or y <= R:
                            abs_dist = total_dist - path_len
                        else:
                            abs_dist = path_len

                    energy = 2 * (h[x] + h[y]) + abs_dist
                    max_energy = max(max_energy, energy)

        results.append(str(max_energy))

    return '\n'.join(results)

