    dp = [[False] * (MAX_DIFF + 1) for _ in range(n + 1)]
    dp[0][OFFSET] = True  # Start with difference 0

    # path[i][diff] = (prev_diff, choice) for reconstruction
    path = [[None] * (MAX_DIFF + 1) for _ in range(n + 1)]

    for i in range(n):
        current_char = s[i]

        for diff in range(MAX_DIFF + 1):
            # Check if this state is reachable
            if not dp[i][diff]:
                continue

            # Before this hand, check if we're already at k (invalid)
            current_abs = abs(diff - OFFSET)
            if current_abs == k and i < n:
                continue  # Should have already been caught, but double-check

            # Try all possible moves
            # W: diff increases by 1
            if current_char == 'W' or current_char == '?':
                new_diff = diff + 1
                if new_diff <= MAX_DIFF and new_diff >= 0:
                    if dp[i + 1][new_diff] is False:
                        dp[i + 1][new_diff] = True
                        path[i + 1][new_diff] = (diff, 'W')

            # L: diff decreases by 1
            if current_char == 'L' or current_char == '?':
                new_diff = diff - 1
                if new_diff <= MAX_DIFF and new_diff >= 0:
                    if dp[i + 1][new_diff] is False:
                        dp[i + 1][new_diff] = True
                        path[i + 1][new_diff] = (diff, 'L')

            # D: diff stays same
            if current_char == 'D' or current_char == '?':
                if dp[i + 1][diff] is False:
                    dp[i + 1][diff] = True
                    path[i + 1][diff] = (diff, 'D')

