def find_set_part(tot_a, tot_b, n):
    # Find n valid sets
    sols = []
    min_w = 25

    def search(ia, ib, it, cur):
        if it == n and ia == 0 and ib == 0:
            sols.append(cur[:])
            return
        if it < 0 or ia < 0 or ib < 0:
            return

        for a_set in range(max(min_w-2, 0), ia + 1):
            for b_set in range(max(min_w-2, 0), ib + 1):
                # Simple valid check: someone must win and be ahead by 2
                if min_w <= a_set and b_set < min_w-2 and a_set - b_set >= 2:
                    cur.append((a_set, b_set))
                    search(ia - a_set, ib - b_set, it - 1, cur)
                    cur.pop()
                if min_w <= b_set and a_set < min_w-2 and b_set - a_set >= 2:
                    cur.append((a_set, b_set))
                    search(ia - a_set, ib - b_set, it - 1, cur)
                    cur.pop()
                if a_set >= min_w-2 and b_set >= min_w-2 and abs(a_set - b_set) >= 2:
                    cur.append((a_set, b_set))
                    search(ia - a_set, ib - b_set, it - 1, cur)
                    cur.pop()

    search(tot_a, tot_b, n, [])
    return sols[:5] if sols else None

