                for e in range(1, max_pow):
                    p = (p * A[a][b]) % MOD
                    powers[a][b][e] = p

    # Enumerate pivots and their intervals
    for t in range(1, n + 1):
        # Columns before t must form nested sequences ending at [L, R]
        # Columns after t must form sequences starting at [L, R]
        for L in range(1, m + 1):
