        [(0,1), (1,0), (1,1), (1,2)],   # T down:  .#. /  ###
        [(0,0), (0,1), (1,1), (2,1)],   # T left:  .#. /  #..
        [(0,1), (1,0), (1,1), (2,0)],   # T right: .#. /  ..#
    ]

