        """Check if shape can be placed at (r, c)"""
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= m:
                return False
            if grid[nr][nc] != '.':
                return False
        return True

    def place_shape(grid, shape, r, c, char):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
